43	// newConcurrentAmendRegistry 构造并发更正的固定初始配载：C1 承重 100 千克，
44	// G1、G2 各 30 千克、目的地上海、都允许混装，两件已装入 C1（已用 60 千克、
45	// 剩余 40 千克，清单为 [G1 G2]）。每轮并发都从一份全新配载独立开始。
46	func newConcurrentAmendRegistry(t *testing.T) *Registry {
47		t.Helper()
48		r := NewRegistry()
49		mustRegisterCompartment(t, r, "C1", 100)
50		mustRegisterCargo(t, r, "G1", 30, "上海", true)
51		mustRegisterCargo(t, r, "G2", 30, "上海", true)
52		if _, err := r.Adjust("load-g1-g2", []Op{
53			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
54			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
55		}); err != nil {
56			t.Fatalf("初始装载失败: %v", err)
57		}
58		cpt, err := r.Compartment("C1")
59		if err != nil {
60			t.Fatal(err)
61		}
62		if cpt.MaxWeight != 100 || cpt.UsedWeight != 60 || cpt.RemainingWeight != 40 {
63			t.Fatalf("初始配载应为 C1 已用 60/剩余 40，实际 %+v", cpt)
64		}
65		if got := cargoIDs(*cpt); !reflect.DeepEqual(got, []string{"G1", "G2"}) {
66			t.Fatalf("初始舱位清单应为 [G1 G2]，实际 %v", got)
67		}
68		return r
69	}
70	
71	// runConcurrentAmendRound 在同一个登记处上让两次更正从同一道起跑线后并发
72	// 提交：分别把 G1、G2 改为 newWeight 千克，目的地（上海）与混装许可（允许）
73	// 保持原值。delayG1/delayG2 > 0 时对应更正开闸后先等待该时长再提交，用于
74	// 在多轮中覆盖两种生效先后；均为 0 时是纯粹的同时锁竞争。返回登记处与两次
75	// 更正各自的结果，由调用方按场景核对。
76	func runConcurrentAmendRound(t *testing.T, newWeight int64, delayG1, delayG2 time.Duration) (*Registry, []amendOutcome) {
77		t.Helper()
78		r := newConcurrentAmendRegistry(t)
79	
80		start := make(chan struct{})
81		outcomes := make(chan amendOutcome, 2)
82		var wg sync.WaitGroup
83		submit := func(cargoID string, delay time.Duration) {
84			defer wg.Done()
85			<-start
86			if delay > 0 {
87				time.Sleep(delay)
88			}
89			err := r.AmendCargo(cargoID, newWeight, "上海", true)
90			outcomes <- amendOutcome{cargoID: cargoID, newWeight: newWeight, err: err}
91		}
92		wg.Add(2)
93		go submit("G1", delayG1)
94		go submit("G2", delayG2)
95		close(start)
96		wg.Wait()
97		close(outcomes)
98	
99		got := make([]amendOutcome, 0, 2)
100		for o := range outcomes {
101			got = append(got, o)
102		}
103		return r, got
104	}
105	
106	// assertAmendOverweightRound 核对超重竞争轮：恰好一次成功、一次超重拒绝，
107	// 错误结构、最终舱位重量与两件货物资料全部符合要求。返回成功更正的货物
108	// 编号（G1 或 G2，业务允许任意一件先成功，不规定固定成功者）。
109	func assertAmendOverweightRound(t *testing.T, r *Registry, outcomes []amendOutcome) string {
110		t.Helper()
111	
112		var winnerID string
113		var loser *amendOutcome
114		successes, failures := 0, 0
115		for i := range outcomes {
116			o := &outcomes[i]
117			if o.err == nil {
118				successes++
119				winnerID = o.cargoID
120			} else {
121				failures++
122				loser = o
123			}
124		}
125		if successes != 1 || failures != 1 {
126			t.Fatalf("两次并发更正应恰好一次成功、一次拒绝（不是整体成败的批量操作），"+
127				"实际成功 %d 次、失败 %d 次，结果: %+v", successes, failures, outcomes)
128		}
129		if winnerID != "G1" && winnerID != "G2" {
130			t.Fatalf("成功者编号异常: %q", winnerID)
131		}
132		loserID := loser.cargoID
133		if loserID == winnerID || (loserID != "G1" && loserID != "G2") {
134			t.Fatalf("失败者编号异常: %q（成功者 %q）", loserID, winnerID)
135		}
136	
137		// 被拒绝的更正：现有 ErrOverweight 结构化错误，指向舱位 C1，说明给出
138		// 预计总重量 120 与最大承重 100，不携带调整编号。
139		var se *Error
140		if !errors.As(loser.err, &se) {
141			t.Fatalf("失败更正 %s 应返回 *Error，实际为 %T: %v", loserID, loser.err, loser.err)
142		}
143		if se.Kind != ErrOverweight {
144			t.Fatalf("失败更正 %s 应按超重拒绝，实际为 %s（%v）", loserID, se.Kind, loser.err)
145		}
146		if se.ID != "C1" {
147			t.Fatalf("超重错误应涉及舱位 C1，实际 ID=%q", se.ID)
148		}
149		if se.AdjustmentID != "" {
150			t.Fatalf("更正不携带调整编号，实际 AdjustmentID=%q", se.AdjustmentID)
151		}
152		msg := se.Error()
153		for _, want := range []string{"C1", "120", "100"} {
154			if !strings.Contains(msg, want) {
155				t.Fatalf("超重说明应指出舱位 C1、预计总重量 120 千克与最大承重 100 千克，实际: %s", msg)
156			}
157		}
158	
159		cpt, err := r.Compartment("C1")
160		if err != nil {
161			t.Fatalf("查询 C1 失败: %v", err)
162		}
163		// 最终配载：成功的一件 60、失败的一件保留 30，已用 90、剩余 10。
164		if cpt.MaxWeight != 100 || cpt.UsedWeight != 90 || cpt.RemainingWeight != 10 {
165			t.Fatalf("一次成功一次拒绝后 C1 应已用 90/剩余 10，实际 %+v（成功者 %s）", cpt, winnerID)
166		}
167	
168		// 两件货物的重量与登记资料：成功者 60、失败者仍为 30，都继续装载于 C1，
169		// 目的地与混装许可不变。
170		wantWeight := map[string]int64{winnerID: 60, loserID: 30}
171		views := make(map[string]*CargoView, 2)
172		for _, id := range []string{"G1", "G2"} {
173			cv, err := r.Cargo(id)
174			if err != nil {
175				t.Fatalf("查询货物 %s 失败: %v", id, err)
176			}
177			if !cv.Loaded || cv.CompartmentID != "C1" {
178				t.Fatalf("货物 %s 应继续显示已装载于 C1，实际 %+v（成功者 %s）", id, cv, winnerID)
179			}
180			if cv.Weight != wantWeight[id] {
181				t.Fatalf("货物 %s 重量应为 %d（成功者 60、失败者保留 30），实际 %d（成功者 %s）",
182					id, wantWeight[id], cv.Weight, winnerID)
183			}
184			if cv.Destination != "上海" || !cv.AllowMixed {
185				t.Fatalf("货物 %s 的目的地与混装许可应保持原值（上海、允许混装），实际 %+v", id, cv)
186			}
187			views[id] = cv
188		}
189	
190		// 舱位清单仍完整包含两件、各出现一次，且与货物单独查询逐项一致。
191		if got := cargoIDs(*cpt); !reflect.DeepEqual(got, []string{"G1", "G2"}) {
192			t.Fatalf("C1 清单应完整包含 G1、G2 各一次，实际 %v", got)
193		}
194		if len(cpt.Cargo) != 2 {
195			t.Fatalf("C1 清单应恰好两件货物，实际 %d 件", len(cpt.Cargo))
196		}
197		for _, item := range cpt.Cargo {
198			cv := views[item.ID]
199			if !item.Loaded || item.CompartmentID != "C1" {
200				t.Fatalf("清单中的 %s 应显示已装载于 C1，实际 %+v", item.ID, item)
201			}
202			if item.Weight != cv.Weight || item.Destination != cv.Destination ||
203				item.AllowMixed != cv.AllowMixed {
204				t.Fatalf("清单中 %s 的资料（%d/%s/%t）与货物查询（%d/%s/%t）不一致",
205					item.ID, item.Weight, item.Destination, item.AllowMixed,
206					cv.Weight, cv.Destination, cv.AllowMixed)
207			}
208		}
209		return winnerID
210	}
211	
212	// assertAmendExactCapacityRound 核对恰好够用的竞争轮：两次更正都成功，
213	// 最终已用 100、剩余 0，两件货物均为 50 千克且继续装载于 C1。
214	func assertAmendExactCapacityRound(t *testing.T, r *Registry, outcomes []amendOutcome) {
215		t.Helper()
216		if len(outcomes) != 2 {
217			t.Fatalf("应有两次更正结果，实际 %d 个", len(outcomes))
218		}
219		for _, o := range outcomes {
220			if o.err != nil {
221				t.Fatalf("两件各改为 50 千克后合计恰好 100，%s 的更正不应被拒绝（不能因并发就拒绝）: %v",
222					o.cargoID, o.err)
223			}
224			if o.newWeight != 50 {
225				t.Fatalf("结果记录的新重量应为 50，实际 %d", o.newWeight)
226			}
227		}
228	
229		cpt, err := r.Compartment("C1")
230		if err != nil {
231			t.Fatalf("查询 C1 失败: %v", err)
232		}
233		if cpt.MaxWeight != 100 || cpt.UsedWeight != 100 || cpt.RemainingWeight != 0 {
234			t.Fatalf("两次更正都成功后 C1 应已用 100/剩余 0，实际 %+v", cpt)
235		}
236		if got := cargoIDs(*cpt); !reflect.DeepEqual(got, []string{"G1", "G2"}) {
237			t.Fatalf("C1 清单应完整包含 G1、G2 各一次，实际 %v", got)
238		}
239		for _, id := range []string{"G1", "G2"} {
240			cv, err := r.Cargo(id)
241			if err != nil {
242				t.Fatalf("查询货物 %s 失败: %v", id, err)
243			}
244			if !cv.Loaded || cv.CompartmentID != "C1" || cv.Weight != 50 ||
245				cv.Destination != "上海" || !cv.AllowMixed {
246				t.Fatalf("货物 %s 应为 50 千克、上海、允许混装、仍在 C1，实际 %+v", id, cv)
247			}
248		}
249		for _, item := range cpt.Cargo {
250			cv, _ := r.Cargo(item.ID)
251			if item.Weight != cv.Weight || item.Destination != cv.Destination ||
252				item.AllowMixed != cv.AllowMixed || item.CompartmentID != cv.CompartmentID {
253				t.Fatalf("清单中 %s 的资料与货物查询不一致: %+v vs %+v", item.ID, item, cv)
254			}
255		}
256	}
257	
258	// TestConcurrentAmendSameCompartmentOnlyOneWeightGainTakesEffect 是核心并发
259	// 回归：G1、G2 并发地各自从 30 千克更正为 60 千克。任一更正单独作用于初始
260	// 配载都合法（合计 90），但两次共同生效会达到 120 千克，因此多轮并发中必须
261	// 始终恰好一次成功、另一次按超重拒绝，且两种生效先后都实际出现过（不规定
262	// 哪件成功），无论哪件成功，错误与最终配载都满足各自要求。
263	func TestConcurrentAmendSameCompartmentOnlyOneWeightGainTakesEffect(t *testing.T) {
264		// 前置事实：任一更正单独作用于初始配载都合法，并发下的拒绝只能来自
265		// 两次增重共同占用承重，而不是资料本身错误。
266		t.Run("任一更正单独提交都合法", func(t *testing.T) {
267			for _, id := range []string{"G1", "G2"} {
268				r := newConcurrentAmendRegistry(t)
269				if err := r.AmendCargo(id, 60, "上海", true); err != nil {
270					t.Fatalf("%s 单独改为 60 千克本应合法（合计 90）: %v", id, err)
271				}
272				cv, _ := r.Cargo(id)
273				if cv.Weight != 60 || cv.CompartmentID != "C1" {
274					t.Fatalf("%s 单独更正后应为 60 千克且仍在 C1: %+v", id, cv)
275				}
276				other := map[string]string{"G1": "G2", "G2": "G1"}[id]
277				ov, _ := r.Cargo(other)
278				if ov.Weight != 30 {
279					t.Fatalf("更正 %s 不应影响另一件 %s 的重量", id, other)
280				}
281				cpt, _ := r.Compartment("C1")
282				if cpt.UsedWeight != 90 || cpt.RemainingWeight != 10 {
283					t.Fatalf("%s 单独更正后 C1 应已用 90/剩余 10，实际 %+v", id, cpt)
284				}
285			}
286		})
287	
288		// 并发竞争：多轮覆盖两种先后，并穿插不偏不倚的同时竞争。
289		wins := map[string]int{"G1": 0, "G2": 0}
290		const rounds = 40
291		for i := 0; i < rounds; i++ {
292			var delayG1, delayG2 time.Duration
293			switch i % 4 {
294			case 0:
295				delayG2 = 2 * time.Millisecond // 偏向 G1 先更正
296			case 1:
297				delayG1 = 2 * time.Millisecond // 偏向 G2 先更正
298			case 2:
299				delayG2 = 5 * time.Millisecond // 再次偏向 G1，加大先后差
300			default:
301				// 两次更正零等待同时提交，纯粹的锁竞争。
302			}
303			r, outcomes := runConcurrentAmendRound(t, 60, delayG1, delayG2)
304			wins[assertAmendOverweightRound(t, r, outcomes)]++
305		}
306	
307		// 极端调度下若某种先后始终未出现，补几轮强偏向竞争；仍不出现才判定
308		// 失败。两种生效先后都必须被实际观察到（不规定哪件成功，但任一件都
309		// 应能在并发提交中正常生效）。
310		for j := 0; j < 3 && wins["G1"] == 0; j++ {
311			r, outcomes := runConcurrentAmendRound(t, 60, 0, 25*time.Millisecond)
312			wins[assertAmendOverweightRound(t, r, outcomes)]++
313		}
314		for j := 0; j < 3 && wins["G2"] == 0; j++ {
315			r, outcomes := runConcurrentAmendRound(t, 60, 25*time.Millisecond, 0)
316			wins[assertAmendOverweightRound(t, r, outcomes)]++
317		}
318		if wins["G1"] == 0 || wins["G2"] == 0 {
319			t.Fatalf("经过 %d 轮并发更正仍只观察到一种生效先后（G1 成功 %d 次、G2 成功 %d 次），"+
320				"两种先后都应被接受", rounds, wins["G1"], wins["G2"])
321		}
322		t.Logf("并发更正 %d 轮：G1 成功 %d 次，G2 成功 %d 次（每次均为另一件超重拒绝）",
323			rounds, wins["G1"], wins["G2"])
324	}
325	
326	// TestConcurrentAmendExactCapacityBothWeightGainSucceed 覆盖与超重情形对应的
327	// 恰好够用情形：G1、G2 并发地各从 30 千克更正为 50 千克，共同生效后合计
328	// 恰好 100 千克等于承重，两次都必须成功，最终已用 100、剩余 0。先核对顺序
329	// 提交同样两次成功的基线，再在多轮并发（含两种先后与同时提交）中确认并发
330	// 本身不构成拒绝理由。
331	func TestConcurrentAmendExactCapacityBothWeightGainSucceed(t *testing.T) {
332		// 顺序基线：先改 G1 再改 G2，两次都成功且最终恰好满舱。
333		t.Run("顺序提交两次都成功", func(t *testing.T) {
334			r := newConcurrentAmendRegistry(t)
335			if err := r.AmendCargo("G1", 50, "上海", true); err != nil {
336				t.Fatalf("G1 改为 50 千克应成功（合计 80）: %v", err)
337			}
338			if err := r.AmendCargo("G2", 50, "上海", true); err != nil {
339				t.Fatalf("G2 改为 50 千克应成功（合计恰好 100）: %v", err)
340			}
341			cpt, _ := r.Compartment("C1")
342			if cpt.UsedWeight != 100 || cpt.RemainingWeight != 0 {
343				t.Fatalf("顺序两次更正后 C1 应已用 100/剩余 0，实际 %+v", cpt)
344			}
345		})
346	
347		// 并发：多轮覆盖两种先后与同时提交，每轮两次都必须成功。
348		for i := 0; i < 30; i++ {
349			var delayG1, delayG2 time.Duration
350			switch i % 3 {
351			case 0:
352				delayG2 = 2 * time.Millisecond
353			case 1:
354				delayG1 = 2 * time.Millisecond
355			default:
356				// 零等待同时提交。
357			}
358			r, outcomes := runConcurrentAmendRound(t, 50, delayG1, delayG2)
359			assertAmendExactCapacityRound(t, r, outcomes)
360		}
361	}
362

